/* Venn prototype — collections, disputes, approvals, reports, documents, integrations, team, audit, settings, account */
const prio = c => { const i = inv(c.inv); return Math.round(invBal(i) * Math.max(1, invDaysOver(i)) / 1000) + (c.promise && c.promise < TODAY ? 20 : 0); };
const prioWhy = c => { const i = inv(c.inv); return `${money(invBal(i), i.cur)} × ${invDaysOver(i)} days overdue ÷ 1,000${c.status === 'paused' ? ' (paused: dispute open)' : ''}`; };

/* ---------- collections ---------- */
R(/^\/collections$/, () => {
  const v = vs('coll', { f: 'all' }); let rows = D.cases.filter(c => invBal(inv(c.inv)) > 0);
  const F = { due: c => c.next && c.next <= '2026-11-14', mine: c => c.owner === me().id, paused: c => c.status === 'paused', final: c => c.stage === 'final_notice' }; if (F[v.f]) rows = rows.filter(F[v.f]); rows = rows.sort((a, b) => prio(b) - prio(a));
  return `${pageH('Collections', 'Overdue invoices by priority. Nothing is sent without the right permission or approval.')}
  ${D.integrations.find(x => x.id === 'gmail').status !== 'connected' ? `<div class="banner warn">${ic('info')}<div>No mailbox connected. You can draft messages and mark them as sent manually. <a href="#/integrations">Connect Gmail</a></div></div>` : ''}
  <div class="card"><div class="toolbar">${chipset('coll.f', [['all', 'All'], ['due', 'Due now'], ['mine', 'Mine'], ['final', 'Final notice'], ['paused', 'Paused']], v.f)}</div>
  ${table([{ h: 'Customer / invoice', f: c => `<a href="#/collections/${c.id}"><b>${esc(cust(inv(c.inv).cust).name)}</b></a><div class="small muted">${inv(c.inv).number}</div>` }, { h: 'Balance', cls: 'num', f: c => money(invBal(inv(c.inv)), inv(c.inv).cur) }, { h: 'Days overdue', cls: 'num', f: c => invDaysOver(inv(c.inv)) }, { h: 'Stage', f: c => badge(c.stage) + (c.pendingApproval ? ' <span class="badge b-amber nodot">Approval pending</span>' : '') }, { h: 'Next action', f: c => dt(c.next) }, { h: 'Last contact', f: c => dt(c.last) }, { h: 'Priority', cls: 'num', f: c => `<span title="${esc(prioWhy(c))}" style="border-bottom:1px dotted">${prio(c)}</span>` }, { h: 'Owner', f: c => person(c.owner) }], rows, { href: c => '#/collections/' + c.id })}</div>`;
}, { name: 'coll' });
const caseTl = c => { c.tl = c.tl || [[inv(c.inv).due, 'Invoice became overdue — case opened by nightly job', 'n'], ...(c.last ? [[c.last, 'Reminder sent', 'g']] : []), ...(c.promise ? [[c.last || TODAY, `Promise to pay by ${dt(c.promise)}`, 'b']] : [])]; return c.tl; };
R(/^\/collections\/(\w+)$/, m => {
  const c = byId(D.cases, m[1]); if (!c) return null; const i = inv(c.inv), cu = cust(i.cust), v = vs('cc', { tmpl: 'friendly', draft: '' }), em = D.emails.filter(e => e.cust === cu.id);
  const tmpls = { friendly: 'Friendly reminder', firm: 'Firm reminder', final: 'Final notice' };
  const gen = () => `Hi ${cu.contacts[0].n.split(' ')[0]},\n\n${v.tmpl === 'final' ? `This is a final notice regarding` : v.tmpl === 'firm' ? 'Following up again on' : 'A quick reminder about'} invoice ${i.number} for ${money(i.total, i.cur)}, which was due on ${dt(i.due)}. The outstanding balance is ${money(invBal(i), i.cur)} (${invDaysOver(i)} days overdue).\n\nPlease let us know the expected payment date, or reply if there is anything holding this up.\n\nKind regards,\n${me().name}\n${D.org.name.replace(' (demo)', '')}`;
  const final = v.tmpl === 'final';
  return `${pageH(`${esc(cu.name)} · ${i.number} ${badge(c.stage)}`, `${money(invBal(i), i.cur)} outstanding · ${invDaysOver(i)} days overdue`, '', '<a href="#/collections">Collections</a> / ' + i.number)}
  ${c.status === 'paused' ? `<div class="banner warn">${ic('info')}<div>${c.note}. Automated reminders are paused for this invoice.</div></div>` : ''}${c.pendingApproval ? `<div class="banner">${ic('lock')}<div>A final notice is waiting for Owner approval (<a href="#/approvals/ap4">APR-0004</a>).</div></div>` : ''}
  <div class="grid g3"><div class="col">${card('Case facts', `<dl class="kv"><dt>Invoice</dt><dd><a href="#/invoices/${i.id}">${i.number}</a></dd><dt>Total</dt><dd>${money(i.total, i.cur)}</dd><dt>Balance</dt><dd><b>${money(invBal(i), i.cur)}</b></dd><dt>Due</dt><dd>${dt(i.due)}</dd><dt>Promise to pay</dt><dd>${c.promise ? dt(c.promise) : '—'}</dd><dt>Next action</dt><dd>${dt(c.next)}</dd><dt>Priority</dt><dd>${prio(c)} <span class="small muted">(${prioWhy(c)})</span></dd></dl>`)}${em.length ? card('Customer emails', em.map(e => `<div class="ev"><div class="small"><b>${esc(e.subject)}</b> · ${dt(e.date)}</div><div class="q">${esc(e.body)}</div></div>`).join('')) : ''}</div>
  ${card('Communication timeline', mini(caseTl(c).map(t => `<li><span class="pt ${t[2] === 'g' ? 'g' : t[2] === 'n' ? 'n' : ''}"></span><div class="small">${esc(t[1])}</div><div class="t">${dt(t[0])}</div></li>`)))}
  ${card('Compose reminder', `<div class="field"><label>Template</label><select class="in" onchange="V.cc.tmpl=this.value;V.cc.draft='';render()">${Object.entries(tmpls).map(([k, l]) => `<option value="${k}" ${v.tmpl === k ? 'selected' : ''}>${l}</option>`).join('')}</select></div>
  <div class="field"><label>Draft</label><textarea class="in" rows="11" id="cdraft" aria-label="Draft message">${esc(v.draft || gen())}</textarea></div>
  <div class="small" style="color:var(--teal-700)">✓ Fact check passed: ${money(i.total, i.cur)}, ${money(invBal(i), i.cur)}, ${i.number} and ${dt(i.due)} match records. No fees, threats or guarantees.</div>
  <div class="ai-cap mt8">${ic('info')} AI-drafted from your records · edit before sending</div>
  <div class="row wrap mt16"><button class="btn btn-primary" data-act="sendCase" data-id="${c.id}" ${c.status === 'paused' ? 'disabled' : ''}>${final || !can('collections.send') ? 'Submit for approval' : 'Send reminder'}</button><button class="btn" data-act="markSent" data-id="${c.id}">Mark sent manually</button><button class="btn" data-act="schedule" data-id="${c.id}">Schedule follow-up</button></div>${final ? '<div class="small muted mt8">Final notices always need Owner approval.</div>' : !can('collections.send') ? '<div class="small muted mt8">You can draft but not send; standard reminders go to the Owner for approval.</div>' : ''}`)}</div>`;
}, { name: 'cc' });
ACT.sendCase = el => {
  const c = byId(D.cases, el.dataset.id), v = V.cc, final = v.tmpl === 'final';
  if (final || !can('collections.send')) { const n = D.approvals.length + 1, ap = { id: 'ap' + (++SEQ), number: 'APR-' + String(n).padStart(4, '0'), type: 'collection_email', subject: c.inv, amount: invBal(inv(c.inv)), by: me().id, status: 'pending', created: TODAY, reason: `${final ? 'Final notice' : 'Reminder'} to ${cust(inv(c.inv).cust).name} for ${inv(c.inv).number}.`, ev: ['Invoice ' + inv(c.inv).number], caseId: c.id }; D.approvals.push(ap); c.pendingApproval = true; audit('collection.submitted_for_approval', ap.number, inv(c.inv).number); toast('Submitted for approval'); }
  else { c.last = TODAY; c.next = '2026-11-20'; c.stage = c.stage === 'reminder_1' ? 'reminder_2' : c.stage; caseTl(c).push([TODAY, 'Reminder sent from the connected mailbox (simulated)', 'g']); audit('email.sent', inv(c.inv).number, 'Collection reminder'); toast('Reminder sent (simulated) and logged; follow-up set for 20 Nov'); }
  render();
};
ACT.markSent = el => { const c = byId(D.cases, el.dataset.id); c.last = TODAY; caseTl(c).push([TODAY, 'Marked as sent manually (outside Venn)', 'n']); audit('collection.manual_contact', inv(c.inv).number, 'Marked sent manually'); toast('Recorded as a manual contact'); render(); };
ACT.schedule = el => modal('Schedule follow-up', form('fs', fld('Follow-up date', '<input class="in" type="date" name="d" data-req value="2026-11-20">')), `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-primary" data-act="saveSched" data-id="${el.dataset.id}">Schedule</button>`);
ACT.saveSched = el => { if (!validate($('#fs'))) return; const c = byId(D.cases, el.dataset.id); c.next = $('[name=d]').value; closeOv(); toast('Follow-up scheduled for ' + dt(c.next)); render(); };

/* ---------- disputes ---------- */
R(/^\/disputes$/, () => {
  const v = vs('disp', { f: 'all' }); let rows = D.disputes; if (v.f === 'open') rows = rows.filter(d => !['resolved', 'rejected'].includes(d.status)); if (v.f === 'mine') rows = rows.filter(d => d.assignee === me().id);
  return `${pageH('Disputes', 'Customer claims tracked to resolution', can('disputes.manage') ? `<button class="btn btn-primary" data-act="newDispute">${ic('plus')}New dispute</button>` : '')}<div class="card"><div class="toolbar">${chipset('disp.f', [['all', 'All'], ['open', 'Open'], ['mine', 'Assigned to me']], v.f)}</div>${table([{ h: 'Dispute', f: d => `<a href="#/disputes/${d.id}"><b>${d.number}</b></a>` }, { h: 'Customer / invoice', f: d => `${esc(cust(d.cust).name)}<div class="small muted">${inv(d.inv).number}</div>` }, { h: 'Category', f: d => d.cat }, { h: 'Disputed', cls: 'num', f: d => money(d.amount) }, { h: 'Status', f: d => badge(d.status) }, { h: 'Assignee', f: d => person(d.assignee) }, { h: 'Due', f: d => dt(d.due) }], rows, { href: d => '#/disputes/' + d.id })}</div>`;
}, { name: 'disp' });
R(/^\/disputes\/(\w+)$/, m => {
  const d = byId(D.disputes, m[1]); if (!d) return null; const i = inv(d.inv), em = D.emails.filter(e => e.cust === d.cust && (e.subject.includes(i.number) || e.body.includes(i.number))), done = ['resolved', 'rejected'].includes(d.status); d.notes = d.notes || [];
  d.tl = d.tl || [[d.created, 'Dispute opened', 'b'], ...(d.status === 'awaiting_customer' ? [[d.created, 'Information requested from customer', 'n']] : []), ...(d.resolution ? [[d.due, 'Resolved: ' + d.resolution, 'g']] : [])];
  const next = { open: [['under_review', 'Start review']], under_review: [['awaiting_customer', 'Request info from customer']], awaiting_customer: [['under_review', 'Customer responded']] }[d.status] || [];
  return `${pageH(`${d.number} ${badge(d.status)}`, `${esc(cust(d.cust).name)} · ${esc(d.cat)}`, next.map(n => `<button class="btn" data-act="dStatus" data-id="${d.id}" data-s="${n[0]}">${n[1]}</button>`).join(''), '<a href="#/disputes">Disputes</a> / ' + d.number)}
  ${invDisputed(i) ? `<div class="banner warn">${ic('info')}<div>${i.number} is marked <b>Disputed</b> and automated reminders are paused until this is resolved.</div></div>` : ''}
  <div class="grid g-main"><div class="col">${card('Customer explanation', `<div class="ev"><div class="q" style="border:0;margin:0;padding:0;font-size:14px;color:var(--text)">"${esc(d.expl)}"</div><div class="cap mt8">Source: ${em.length ? 'email ' + dt(em[0].date) : 'recorded by ' + person(d.assignee)} · customer claim, not verified</div></div><dl class="kv mt16"><dt>Invoice</dt><dd><a href="#/invoices/${i.id}">${i.number}</a> (${money(i.total, i.cur)})</dd><dt>Disputed amount</dt><dd><b>${money(d.amount)}</b></dd><dt>Due</dt><dd>${dt(d.due)}</dd></dl>`)}
  ${card('Internal notes', `${d.notes.map(n => `<div class="ev"><div class="small"><b>${person(n[0])}</b> · ${dt(n[1])}</div><div class="q">${esc(n[2])}</div></div>`).join('') || '<div class="muted small">No notes yet.</div>'}<div class="row mt8"><input class="in sp" id="dnote" placeholder="Add an internal note…" aria-label="Internal note"><button class="btn" data-act="dNote" data-id="${d.id}">Add</button></div>`)}
  ${!done ? card('Resolution', form('fr', fld('Outcome', '<select class="in" name="o"><option value="upheld">Upheld — customer is right</option><option value="partial">Partially upheld</option><option value="rejected">Rejected — not supported</option></select>') + fld('Adjustment amount (optional)', `<input class="in num" name="a" inputmode="decimal" placeholder="0.00">`, 'A credit goes to approval before it changes the balance.') + fld('Resolution note', '<textarea class="in" rows="2" data-req name="n"></textarea>')) + `<button class="btn btn-primary" data-act="dResolve" data-id="${d.id}">${can('approvals.decide') ? 'Resolve dispute' : 'Resolve / submit for approval'}</button>`) : card('Resolution', `<p>${esc(d.resolution || 'Rejected')}</p>`)}</div>
  <div class="col">${card('Evidence', `${em.map(e => `<div class="ev"><div class="top"><span class="badge b-neutral nodot">Email</span><span class="sp"></span>${tierBadge(4)}</div><div class="ti mt8">${esc(e.subject)}</div><div class="q">${esc(e.body)}</div></div>`).join('')}<div class="ev"><div class="top"><span class="badge b-neutral nodot">Invoice</span><span class="sp"></span>${tierBadge(2)}</div><div class="ti mt8"><a href="#/invoices/${i.id}">${i.number}</a></div><div class="small muted">${esc(i.desc)} · PO ${esc(i.po) || '—'}</div></div><button class="btn btn-sm" data-act="toast" data-msg="Upload evidence (simulated)">${ic('plus')}Add evidence</button>`)}
  ${card('Timeline', mini(d.tl.map(t => `<li><span class="pt ${t[2] === 'g' ? 'g' : t[2] === 'n' ? 'n' : ''}"></span><div class="small">${esc(t[1])}</div><div class="t">${dt(t[0])}</div></li>`)))}</div></div>`;
}, { name: 'dd' });
ACT.dStatus = el => { const d = byId(D.disputes, el.dataset.id); d.status = el.dataset.s; d.tl.push([TODAY, 'Status: ' + ST[d.status][0], 'n']); audit('dispute.status', d.number, ST[d.status][0]); toast('Status updated'); render(); };
ACT.dNote = el => { const t = $('#dnote').value.trim(); if (!t) return; byId(D.disputes, el.dataset.id).notes.push([me().id, TODAY, t]); render(); };
ACT.dResolve = el => {
  const f = $('#fr'); if (!validate(f)) return; const d = byId(D.disputes, el.dataset.id), g = n => $(`[name=${n}]`, f).value, a = parseFloat(g('a')) || 0, o = g('o'), i = inv(d.inv);
  if (a > invBal(i)) { toast('Adjustment cannot exceed the invoice balance'); return; }
  if (a > 0 && !can('approvals.decide')) { const n = D.approvals.length + 1, ap = { id: 'ap' + (++SEQ), number: 'APR-' + String(n).padStart(4, '0'), type: 'credit', subject: i.id, amount: a, by: me().id, status: 'pending', created: TODAY, reason: `Dispute ${d.number}: ${g('n')}`, ev: ['Dispute ' + d.number], dispute: d.id }; D.approvals.push(ap); D.adjustments.push({ id: 'adj' + (++SEQ), number: 'ADJ-' + String(D.adjustments.length + 1).padStart(4, '0'), inv: i.id, type: 'credit', amount: a, status: 'pending_approval', reason: g('n'), approval: ap.id }); d.status = 'awaiting_internal'; d.tl.push([TODAY, 'Credit proposed — awaiting owner approval', 'n']); audit('approval.requested', ap.number, d.number); toast('Credit submitted for approval; the dispute stays open until decided'); render(); return; }
  if (a > 0) D.adjustments.push({ id: 'adj' + (++SEQ), number: 'ADJ-' + String(D.adjustments.length + 1).padStart(4, '0'), inv: i.id, type: 'credit', amount: a, status: 'applied', reason: g('n'), approval: null });
  d.status = o === 'rejected' ? 'rejected' : 'resolved'; d.resolution = { upheld: 'Upheld', partial: 'Partially upheld', rejected: 'Rejected' }[o] + (a ? ` — credit ${money(a)} applied` : '') + '. ' + g('n'); d.tl.push([TODAY, 'Resolved: ' + d.resolution, 'g']); audit('dispute.resolved', d.number, d.resolution); toast('Dispute resolved'); render();
};

/* ---------- approvals ---------- */
const apEvents = a => { a.events = a.events || [[a.created, 'requested', a.by, a.reason]]; return a.events; };
const apImpact = a => { const i = inv(a.subject); if (!i || !['write_off', 'credit', 'discount'].includes(a.type)) return null; return [invBal(i), Math.max(0, invBal(i) - (a.status === 'approved' ? 0 : a.amount))]; };
R(/^\/approvals$/, () => {
  const o = can('approvals.decide'), v = vs('aps', { tab: 'pending' }); let rows = D.approvals.filter(a => o || a.by === me().id);
  const T = { pending: a => a.status === 'pending', info: a => a.status === 'info_requested', decided: a => ['approved', 'rejected', 'stale', 'withdrawn'].includes(a.status) }; const cnt = t => rows.filter(T[t]).length; rows = rows.filter(T[v.tab]);
  return `${pageH(o ? 'Approval center' : 'My requests', o ? 'Sensitive actions wait here for a decision' : 'Requests you submitted for owner approval')}${tabs('aps.tab', [['pending', 'Pending', cnt('pending')], ['info', 'Info requested', cnt('info')], ['decided', 'Decided', cnt('decided')]], v.tab)}
  <div class="card">${table([{ h: 'Request', f: a => `<a href="#/approvals/${a.id}"><b>${a.number}</b></a>` }, { h: 'Type', f: a => ATYPE[a.type] }, { h: 'Record', f: a => a.subject && inv(a.subject) ? inv(a.subject).number : '—' }, { h: 'Requested by', f: a => person(a.by) }, { h: 'Impact', cls: 'num', f: a => a.type === 'collection_email' ? '—' : money(a.amount) }, { h: 'Age', cls: 'num', f: a => days(a.created, TODAY) + 'd' }, { h: 'Status', f: a => badge(a.status) }], rows, { href: a => '#/approvals/' + a.id, empty: empty(o ? 'No requests in this tab.' : 'You have no requests in this tab.') })}</div>`;
}, { name: 'aps' });
R(/^\/approvals\/(\w+)$/, m => {
  const a = byId(D.approvals, m[1]); if (!a) return null; if (!can('approvals.decide') && a.by !== me().id) return denied('You can only see your own requests.'); const i = a.subject ? inv(a.subject) : null, imp = apImpact(a), pend = a.status === 'pending';
  const stale = pend && imp && invBal(i) < a.amount;
  return `${pageH(`${a.number} ${badge(a.status)}`, `${ATYPE[a.type]}${i ? ' · ' + i.number : ''} · requested by ${person(a.by)}`, '', `<a href="#/approvals">${can('approvals.decide') ? 'Approvals' : 'My requests'}</a> / ${a.number}`)}
  ${stale ? `<div class="banner warn">${ic('info')}<div><b>The invoice changed since this was requested.</b> Its balance is now ${money(invBal(i), i.cur)}. Approving will mark this request stale instead of applying an outdated amount.</div></div>` : ''}
  <div class="grid g-main"><div class="col">${card('Request', `<dl class="kv"><dt>Type</dt><dd>${ATYPE[a.type]}</dd><dt>Requested</dt><dd>${dt(a.created)} by ${person(a.by)}</dd><dt>Amount</dt><dd><b>${a.type === 'collection_email' ? 'Final notice email' : money(a.amount)}</b></dd></dl><div class="mt16"><div class="cap">Reason</div><p>${esc(a.reason)}</p></div>${a.type === 'refund_record' ? `<div class="banner mt16">${ic('info')}<div>Venn records the decision only. The refund itself is sent from your bank, and Venn will link it when the outgoing transaction appears in an import.</div></div>` : ''}`)}
  ${imp ? card('Financial impact', `<div class="grid g2"><div class="kpi"><div class="l">Invoice balance now</div><div class="v">${money(imp[0], i.cur)}</div></div><div class="kpi"><div class="l">Balance after approval</div><div class="v">${money(a.status === 'approved' ? invBal(i) : imp[1], i.cur)}</div></div></div>`) : ''}
  ${card('Evidence', `<ul class="tl" style="margin:0">${a.ev.map(e => `<li><span class="pt n"></span><div class="small">${esc(e)}</div></li>`).join('')}</ul>${a.inv ? `<a class="btn btn-sm" href="#/investigations/${a.inv}">Open investigation</a>` : ''}${i ? ` <a class="btn btn-sm" href="#/invoices/${i.id}">Open ${i.number}</a>` : ''}`)}
  ${pend && can('approvals.decide') ? card('Decision', a.by === me().id ? '<div class="banner warn">You cannot decide your own request.</div>' : `<div class="row wrap"><button class="btn btn-primary" data-act="decide" data-id="${a.id}" data-d="approve">Approve</button><button class="btn btn-danger" data-act="decide" data-id="${a.id}" data-d="reject">Reject</button><button class="btn" data-act="decide" data-id="${a.id}" data-d="info">Request more information</button></div><div class="small muted mt8">Decisions are immutable. Corrections are made with a new, linked request.</div>`) : ''}
  ${pend && !can('approvals.decide') ? `<button class="btn" data-act="withdraw" data-id="${a.id}">Withdraw request</button>` : ''}</div>
  <div>${card('History', mini(apEvents(a).map(e => `<li><span class="pt ${e[1] === 'approved' ? 'g' : e[1] === 'requested' ? '' : 'n'}"></span><div class="small"><b>${e[1].replace('_', ' ')}</b> · ${e[2] === 'system' ? 'System' : person(e[2])}</div>${e[3] ? `<div class="small muted">${esc(e[3])}</div>` : ''}<div class="t">${dt(e[0])}</div></li>`)))}</div></div>`;
}, { name: 'ad' });
ACT.decide = el => {
  const a = byId(D.approvals, el.dataset.id), d = el.dataset.d; if (a.by === me().id) { toast('You cannot decide your own request'); return; }
  const L = { approve: 'Approve', reject: 'Reject', info: 'Request more information' }[d];
  modal(L + ' ' + a.number, form('fk', fld(d === 'reject' ? 'Reason (required)' : 'Comment (optional)', `<textarea class="in" rows="3" name="c" ${d === 'approve' ? '' : 'data-req'}></textarea>`)), `<button class="btn" data-act="closeOv">Cancel</button><button class="btn ${d === 'reject' ? 'btn-danger' : 'btn-primary'}" data-act="doDecide" data-id="${a.id}" data-d="${d}">${L}</button>`);
};
ACT.doDecide = el => {
  if (!validate($('#fk'))) return; const a = byId(D.approvals, el.dataset.id), d = el.dataset.d, c = $('[name=c]').value, i = a.subject ? inv(a.subject) : null, x = a.inv ? byId(D.investigations, a.inv) : null; apEvents(a);
  if (d === 'approve' && i && ['write_off', 'credit', 'discount'].includes(a.type) && invBal(i) < a.amount) { a.status = 'stale'; a.events.push([TODAY, 'stale', 'system', 'Invoice balance changed before execution']); audit('approval.stale', a.number, 'Not applied'); closeOv(); toast('Marked stale: the invoice changed, nothing was applied'); return render(); }
  if (d === 'approve') {
    a.status = 'approved'; a.decided = me().id; a.decidedAt = TODAY; a.comment = c;
    D.adjustments.filter(j => j.approval === a.id).forEach(j => j.status = 'applied');
    if (a.type === 'refund_record') D.adjustments.push({ id: 'adj' + (++SEQ), number: 'ADJ-' + String(D.adjustments.length + 1).padStart(4, '0'), inv: a.subject, type: 'refund_record', amount: a.amount, status: 'applied', reason: 'Refund due recorded (executed in bank)', approval: a.id });
    const cs = a.caseId ? byId(D.cases, a.caseId) : a.subject === 'i44' ? byId(D.cases, 'cc2') : null; if (cs && a.type === 'collection_email') { cs.pendingApproval = false; cs.last = TODAY; cs.next = '2026-11-20'; caseTl(cs).push([TODAY, 'Approved message sent from the connected mailbox (simulated)', 'g']); }
    if (a.dispute) { const dd = byId(D.disputes, a.dispute); dd.status = 'resolved'; dd.resolution = `Credit ${money(a.amount)} approved`; dd.tl.push([TODAY, dd.resolution, 'g']); }
    if (x) { x.action = a.plannedAction || ATYPE[a.type] + ' approved'; x.actionDate = TODAY; x.status = x.status === 'awaiting_approval' ? 'monitoring' : x.status; x.followUp = '2026-11-20'; x.timeline.unshift([TODAY, `${a.number} approved by ${me().name}; action recorded`, 'g']); }
  } else if (d === 'reject') { a.status = 'rejected'; a.decided = me().id; a.decidedAt = TODAY; a.comment = c; D.adjustments.filter(j => j.approval === a.id).forEach(j => j.status = 'rejected'); if (x) { x.status = 'ready_for_review'; x.timeline.unshift([TODAY, `${a.number} rejected: ${c}`, 'n']); } const cs = a.caseId ? byId(D.cases, a.caseId) : null; if (cs) cs.pendingApproval = false; }
  else { a.status = 'info_requested'; }
  a.events.push([TODAY, { approve: 'approved', reject: 'rejected', info: 'info_requested' }[d], me().id, c]); audit('approval.' + { approve: 'approved', reject: 'rejected', info: 'info_requested' }[d], a.number, c || ATYPE[a.type]); closeOv(); toast({ approve: 'Approved and executed — audit-logged', reject: 'Rejected — requester notified', info: 'Information requested' }[d]); render();
};
ACT.withdraw = el => { const a = byId(D.approvals, el.dataset.id); a.status = 'withdrawn'; D.adjustments.filter(j => j.approval === a.id).forEach(j => j.status = 'rejected'); audit('approval.withdrawn', a.number, ''); toast('Request withdrawn'); render(); };

/* ---------- analytics & reports ---------- */
const REPORTS = [['aging', 'Receivables aging', 'f', 'Open invoice balances grouped by days past due as of today. Current means not yet due.'], ['outstanding-trend', 'Outstanding balance trend', 'f', 'Total AR at each weekly snapshot. Snapshots are stored nightly, so history does not change when records are edited.'], ['overdue-trend', 'Overdue trend', 'f', 'Overdue balance at each weekly snapshot.'], ['collection-effectiveness', 'Collection effectiveness', 'f', 'Amount allocated to invoices that were overdue at payment time ÷ (that amount + currently overdue balance), last 30 days.'], ['verified-recovery', 'Verified recovered amounts', 'f', 'Sum of source-verified payments allocated after the first Venn action on that invoice. Shows correlation with Venn activity, not proof that Venn caused the payment.'], ['customer-payment-behaviour', 'Customer payment behaviour', 'f', 'Per customer: invoices fully paid, how many were paid after the due date, average days late. Computed from stored records.'], ['reconciliation-performance', 'Reconciliation performance', 'o', 'How allocations were created: automatically by rule R1, by a person confirming a suggestion, or manually.'], ['discrepancy-categories', 'Discrepancy categories', 'o', 'Count and exposure of discrepancies by type.'], ['investigation-resolution', 'Investigation resolution time', 'o', 'Days from opening to resolution for resolved investigations.']];
R(/^\/analytics$/, () => {
  const a = aging(), dc = Object.entries(D.discrepancies.reduce((m, d) => (m[d.type] = (m[d.type] || 0) + 1, m), {})), rec = D.investigations.filter(x => x.outcome === 'recovered_verified');
  return `${pageH('Analytics', 'Every figure comes from stored records and links to its source', `<a class="btn" href="#/reports">All reports</a>`)}<div class="grid g2">
  ${chartCard('Receivables aging (USD)', agingChart(a)).replace('Receivables aging (USD)', '<a href="#/reports/aging">Receivables aging (USD)</a>')}
  ${chartCard('<a href="#/reports/outstanding-trend">Outstanding balance trend ($k)</a>', lineChart(D.trend.labels, [D.trend.total], ['#3157D5']))}
  ${card('<a href="#/reports/overdue-trend">Overdue trend ($k)</a>', lineChart(D.trend.labels, [D.trend.overdue], ['#DC2626']))}
  ${card('<a href="#/reports/discrepancy-categories">Discrepancy categories</a>', hbars(dc.map(([t, n]) => ({ l: DTYPE[t], v: n, href: '#/reports/discrepancy-categories' }))).replace(/\$/g, '').replace(/(\d+)\.00/g, '$1'))}
  ${card('<a href="#/reports/verified-recovery">Verified recovered</a>', `<div class="kpi" style="border:0;padding:0"><div class="v" style="color:var(--teal-700)">${money(sum(D.investigations, verifiedRecovered))}</div><div class="d">${rec.length} investigation(s) with verified recovery. Payments received after Venn activity; not proof of causation.</div></div>`)}
  ${card('<a href="#/reports/collection-effectiveness">Collection effectiveness</a>', `<div class="kpi" style="border:0;padding:0"><div class="v">${collectionPerf()}%</div><div class="d">Last 30 days. Formula on the report page.</div></div>`)}</div>`;
}, { name: 'an' });
R(/^\/reports$/, () => `${pageH('Reports', can('reports.financial') ? 'Financial and operational reports' : 'Operational reports')}<div class="card"><div class="card-b flush">${REPORTS.filter(r => r[2] === 'o' || can('reports.financial')).map(r => `<a class="row" style="padding:14px 20px;border-bottom:1px solid var(--border);color:var(--text)" href="#/reports/${r[0]}"><div class="sp"><b>${r[1]}</b><div class="small muted">${r[3]}</div></div><span class="badge b-${r[2] === 'o' ? 'blue' : 'neutral'} nodot">${r[2] === 'o' ? 'Operational' : 'Financial'}</span></a>`).join('')}</div></div>`, { name: 'rp' });
R(/^\/reports\/([\w-]+)$/, m => {
  const r = REPORTS.find(x => x[0] === m[1]); if (!r) return null; if (r[2] === 'f' && !can('reports.financial')) return denied('This is a financial report. Ask an owner for access.');
  const v = vs('rep', { c: '' }); let body = '';
  if (m[1] === 'aging') body = agingChart(aging()) + `<div class="mt16">${table([{ h: 'Invoice', f: i => `<a href="#/invoices/${i.id}">${i.number}</a>` }, { h: 'Customer', f: i => esc(cust(i.cust).name) }, { h: 'Days over', cls: 'num', f: i => invDaysOver(i) || 'Current' }, { h: 'Balance', cls: 'num', f: i => money(invBal(i), i.cur) }], openInvoices().filter(i => i.cur === 'USD' && (!v.c || i.cust === v.c)).sort((a, b) => invDaysOver(b) - invDaysOver(a)), { href: i => '#/invoices/' + i.id })}</div>`;
  if (m[1] === 'outstanding-trend' || m[1] === 'overdue-trend') { const s = m[1] === 'overdue-trend' ? D.trend.overdue : D.trend.total; body = lineChart(D.trend.labels, [s], [m[1] === 'overdue-trend' ? '#DC2626' : '#3157D5']) + `<div class="mt16">${table([{ h: 'Snapshot', f: x => x[0] }, { h: '$k', cls: 'num', f: x => x[1] }], D.trend.labels.map((l, k) => [l, s[k]]))}</div>`; }
  if (m[1] === 'collection-effectiveness') body = `<div class="kpi"><div class="l">Effectiveness</div><div class="v">${collectionPerf()}%</div></div><div class="mt16">${table([{ h: 'Payment', f: a => pay(a.pay).number }, { h: 'Invoice', f: a => inv(a.inv).number }, { h: 'Due', f: a => dt(inv(a.inv).due) }, { h: 'Paid', f: a => dt(a.at) }, { h: 'Allocated', cls: 'num', f: a => money(a.amount) }], D.allocations.filter(a => !a.voided && a.at >= '2026-10-14' && inv(a.inv).due < a.at))}</div>`;
  if (m[1] === 'verified-recovery') body = table([{ h: 'Investigation', f: x => `<a href="#/investigations/${x.id}">${x.number}</a>` }, { h: 'Invoice', f: x => inv(x.inv).number }, { h: 'Action date', f: x => dt(x.actionDate) }, { h: 'Verified recovered', cls: 'num', f: x => `<b>${money(verifiedRecovered(x))}</b>` }, { h: 'Components', f: x => D.allocations.filter(a => a.inv === x.inv && !a.voided && pay(a.pay).date >= x.actionDate).map(a => `${pay(a.pay).number} (${money(a.amount)})`).join(', ') }], D.investigations.filter(x => verifiedRecovered(x) > 0), { href: x => '#/investigations/' + x.id });
  if (m[1] === 'customer-payment-behaviour') body = table([{ h: 'Customer', f: c => `<a href="#/customers/${c.id}">${esc(c.name)}</a>` }, { h: 'Fully paid', cls: 'num', f: c => custStats(c).paidN }, { h: 'Paid late', cls: 'num', f: c => custStats(c).late }, { h: 'Avg days late', cls: 'num', f: c => custStats(c).avgLate ?? '—' }, { h: 'Open balance', cls: 'num', f: c => money(custStats(c).open, c.cur) }], D.customers);
  if (m[1] === 'reconciliation-performance') { const g = k => D.allocations.filter(a => !a.voided && a.method === k).length; body = hbars([{ l: 'Auto-applied (R1)', v: g('auto_rule') }, { l: 'Suggestion confirmed', v: g('suggestion_confirmed') }, { l: 'Manual', v: g('manual') }]).replace(/\$/g, '').replace(/(\d+)\.00/g, '$1') + `<div class="small muted mt8">Counts of active allocations by method.</div>`; }
  if (m[1] === 'discrepancy-categories') body = table([{ h: 'Type', f: t => DTYPE[t[0]] }, { h: 'Count', cls: 'num', f: t => t[1] }, { h: 'Exposure (USD)', cls: 'num', f: t => money(t[2]) }], Object.entries(D.discrepancies.filter(d => d.cur === 'USD').reduce((o, d) => { o[d.type] = o[d.type] || [d.type, 0, 0]; o[d.type][1]++; o[d.type][2] += d.exposure; return o; }, {})).map(e => e[1]));
  if (m[1] === 'investigation-resolution') { const rs = D.investigations.filter(x => x.status === 'resolved'), ds = rs.map(x => days(x.created, x.resolved)).sort((a, b) => a - b); body = `<div class="kpi"><div class="l">Median days to resolve</div><div class="v">${ds.length ? ds[Math.floor(ds.length / 2)] : '—'}</div></div><div class="mt16">${table([{ h: 'Investigation', f: x => `<a href="#/investigations/${x.id}">${x.number}</a>` }, { h: 'Opened', f: x => dt(x.created) }, { h: 'Resolved', f: x => dt(x.resolved) }, { h: 'Days', cls: 'num', f: x => days(x.created, x.resolved) }], rs)}</div>`; }
  return `${pageH(r[1], '', `${can('reports.export') ? `<button class="btn" data-act="toast" data-msg="CSV export queued — formula characters escaped, action audit-logged (simulated)">${ic('dl')}Export CSV</button>` : ''}`, '<a href="#/reports">Reports</a> / ' + r[1])}<div class="banner">${ic('info')}<div><b>How this is calculated.</b> ${r[3]}</div></div><div class="card"><div class="toolbar"><select class="in" aria-label="Date range"><option>Last 30 days</option><option>Last 90 days</option></select><select class="in" aria-label="Customer" onchange="V.rep.c=this.value;render()"><option value="">All customers</option>${D.customers.map(c => `<option value="${c.id}" ${v.c === c.id ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select><select class="in" aria-label="Currency"><option>USD</option><option>EUR</option></select></div><div class="card-b">${body}</div></div>`;
}, { name: 'rep' });

/* ---------- documents ---------- */
R(/^\/documents$/, () => `${pageH('Documents', 'Contracts, purchase orders, remittance advices and invoices', `<button class="btn btn-primary" data-act="uploadDoc">${ic('up')}Upload</button>`)}<div class="card">${table([{ h: 'Name', f: d => `<a href="#" data-act="viewDoc" data-id="${d.id}">${ic('file')} ${esc(d.name)}</a>` }, { h: 'Type', f: d => d.type }, { h: 'Linked to', f: d => custLink(d.cust) }, { h: 'Uploaded', f: d => `${dt(d.at)} by ${person(d.by)}` }, { h: 'Pages', cls: 'num', f: d => d.pages }, { h: 'Status', f: d => d.status === 'ready' ? '<span class="badge b-green">Ready</span>' : `<a class="badge b-amber" href="#/invoices/pdf-review">Needs review</a>` }], D.docs)}</div>`, { name: 'docs' });
ACT.viewDoc = el => { const d = byId(D.docs, el.dataset.id); drawer(esc(d.name), `<div class="pdf"><b>${esc(d.type)}</b><p class="mt16 small muted">Preview (demo). Text layer extracted; embedded for evidence search within this organization only.</p><p class="mt16">"Invoices are payable within thirty (30) days of the invoice date. Any dispute must be raised in writing within ten (10) business days."</p></div><div class="small muted mt8">Opened via a short-lived signed URL after a permission check in the real product.</div>`, `<a class="btn" href="#" data-act="closeOv">Close</a>`, true); };
ACT.uploadDoc = () => drawer('Upload document', `<div class="drop">${ic('up')}<p><b>Drop a PDF, PNG, JPG or CSV</b></p><p class="small muted">Up to 20 MB. File type is checked by content, then scanned before processing.</p><button class="btn btn-primary mt16" data-act="doUpload">Use sample PDF</button></div>`);
ACT.doUpload = () => { D.docs.unshift({ id: 'dc' + (++SEQ), name: 'Sample_PO_scan.pdf', type: 'Purchase order', cust: null, by: me().id, at: TODAY, status: 'ready', pages: 1 }); audit('document.uploaded', 'Sample_PO_scan.pdf', 'Scan clean'); closeOv(); toast('Uploaded, scanned and text-extracted (simulated)'); render(); };

/* ---------- integrations ---------- */
R(/^\/integrations$/, () => {
  const cats = ['Email', 'Accounting', 'Payments & Banking', 'Imports'];
  return `${pageH('Integrations', 'Connect the sources Venn reads from')}<div class="banner">${ic('info')}<div>Prototype: connection states are simulated. In the real product a source shows <b>Connected</b> only after a live API call succeeds, and "Coming soon" sources cannot be connected.</div></div>${cats.map(c => `<h3 class="mt24 mb16">${c}</h3><div class="grid g2">${D.integrations.filter(x => x.cat === c).map(x => `<div class="card"><div class="card-b"><div class="prov"><div class="lg">${x.name.slice(0, 2)}</div><div class="sp"><div class="row"><b>${x.name}</b><span class="sp"></span>${badge(x.status)}</div><div class="small muted mt8">${x.desc}</div>${x.err ? `<div class="small mt8" style="color:var(--warning-700)">${x.err}</div>` : ''}${x.sync ? `<div class="small muted mt8">Last sync ${x.sync}</div>` : ''}<div class="row mt16">${x.status === 'soon' ? '<button class="btn btn-sm" disabled>Coming soon</button>' : x.status === 'disconnected' ? `<button class="btn btn-primary btn-sm" data-act="connect" data-id="${x.id}">Connect</button>` : x.note ? '<span class="small muted">' + x.note + '</span>' : `<a class="btn btn-sm" href="#/integrations/${x.id}">Manage</a>`}${x.status === 'attention' ? `<button class="btn btn-primary btn-sm" data-act="connect" data-id="${x.id}">Reconnect</button>` : ''}</div></div></div></div></div>`).join('')}</div>`).join('')}`;
}, { name: 'int' });
ACT.connect = el => { const x = byId(D.integrations, el.dataset.id); modal('Connect ' + x.name, `<p>Venn will ask ${x.name} for these permissions:</p><ul>${x.scopes.map(s => `<li>${s}</li>`).join('')}</ul><div class="banner mt16">${ic('info')}<div>You will be redirected to ${x.name} to approve. Tokens are encrypted and never shown. You can disconnect at any time.</div></div>`, `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-primary" data-act="doConnect" data-id="${x.id}">Continue to ${x.name} (simulated)</button>`); };
ACT.doConnect = el => { const x = byId(D.integrations, el.dataset.id); x.status = 'connected'; x.err = ''; x.acct = x.acct || 'demo-account'; x.sync = '13 Nov ' + new Date().toTimeString().slice(0, 5); audit('integration.connected', x.name, 'Simulated'); closeOv(); toast('Simulated connection. The real product verifies with a live API call first.'); render(); };
R(/^\/integrations\/(\w+)$/, m => {
  const x = byId(D.integrations, m[1]); if (!x) return null;
  return `${pageH(`${x.name} ${badge(x.status)}`, x.desc, `<button class="btn" data-act="toast" data-msg="Sync queued (simulated)">Sync now</button><button class="btn btn-danger" data-act="disconnect" data-id="${x.id}">Disconnect</button>`, '<a href="#/integrations">Integrations</a> / ' + x.name)}
  ${x.err ? `<div class="banner warn">${ic('info')}<div>${x.err}</div></div>` : ''}<div class="grid g-main"><div class="col">${card('Sync history', table([{ h: 'Time', f: r => r[0] }, { h: 'Fetched', cls: 'num', f: r => r[1] }, { h: 'Result', f: r => r[2] }], [[x.sync || '—', 12, '<span class="badge b-green nodot">Success</span>'], ['12 Nov 22:09', 31, x.err ? '<span class="badge b-red nodot">Token expired</span>' : '<span class="badge b-green nodot">Success</span>'], ['11 Nov 22:08', 4, '<span class="badge b-green nodot">Success</span>']]), '', true)}${x.id === 'gmail' ? card('Mail filter', `<div class="small muted mb16">Only messages matching this filter are stored.</div><div class="row wrap"><span class="badge b-neutral nodot">From or to known customer contacts</span><span class="badge b-neutral nodot">Mentions an invoice number</span><span class="badge b-neutral nodot">Finance keywords</span></div>`) : ''}</div>
  <div class="col">${card('Connection', `<dl class="kv"><dt>Account</dt><dd>${esc(x.acct || '—')}</dd><dt>Status</dt><dd>${badge(x.status)}</dd><dt>Last sync</dt><dd>${x.sync || '—'}</dd></dl>`)}${card('Permissions granted', `<ul style="margin:0;padding-left:18px">${(x.scopes || []).map(s => `<li class="small">${s}</li>`).join('')}</ul>`)}</div></div>`;
}, { name: 'intd' });
ACT.disconnect = el => modal('Disconnect ' + byId(D.integrations, el.dataset.id).name + '?', `<p>Tokens are revoked at the provider and deleted. What should happen to data already synced?</p><div class="check mt8"><input type="radio" name="dd" checked> <span>Keep synced data</span></div><div class="check mt8"><input type="radio" name="dd"> <span>Delete synced data</span></div>`, `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-danger" data-act="doDisc" data-id="${el.dataset.id}">Disconnect</button>`);
ACT.doDisc = el => { const x = byId(D.integrations, el.dataset.id); x.status = 'disconnected'; x.sync = ''; x.err = ''; audit('integration.disconnected', x.name, ''); closeOv(); toast('Disconnected'); go('#/integrations'); };

/* ---------- team & permissions ---------- */
const PERMS = [['customers.manage', 'Create and edit customers'], ['invoices.manage', 'Create and edit invoices'], ['invoices.import', 'Import invoices'], ['payments.import', 'Import payments'], ['reconciliation.allocate', 'Confirm matches and allocate'], ['investigations.manage', 'Manage investigations'], ['collections.send', 'Send standard reminders without approval'], ['disputes.manage', 'Manage disputes'], ['reports.financial', 'View financial reports'], ['audit.view', 'View organization audit log']];
const LOCKED = [['approvals.decide', 'Approve or reject requests'], ['integrations.manage', 'Manage integrations'], ['team.manage', 'Manage team and roles'], ['settings.manage', 'Change organization settings'], ['remittance.manage', 'Change remittance details']];
const permOn = { 'customers.manage': 1, 'invoices.manage': 1, 'invoices.import': 1, 'payments.import': 1, 'reconciliation.allocate': 1, 'investigations.manage': 1, 'collections.send': 0, 'disputes.manage': 1, 'reports.financial': 0, 'audit.view': 0 };
const permList = () => PERMS.map(([k, l]) => `<div class="row" style="padding:8px 0;border-bottom:1px solid var(--border)"><span class="sp">${l}<div class="mono muted">${k}</div></span><button class="switch ${permOn[k] ? 'on' : ''}" role="switch" aria-checked="${!!permOn[k]}" aria-label="${l}" data-act="togPerm" data-k="${k}"></button></div>`).join('') + LOCKED.map(([k, l]) => `<div class="row" style="padding:8px 0;border-bottom:1px solid var(--border)"><span class="sp">${l}<div class="mono muted">${k}</div></span><span class="small muted">${ic('lock')} Owner only</span><button class="switch" disabled aria-label="${l} (locked)"></button></div>`).join('');
ACT.togPerm = el => { permOn[el.dataset.k] = permOn[el.dataset.k] ? 0 : 1; audit('permission.changed', 'AR Specialist role', `${el.dataset.k}: ${permOn[el.dataset.k] ? 'on' : 'off'}`); toast('Permission updated — takes effect on the next request'); render(); };
R(/^\/team$/, () => `${pageH('Team', 'Members and pending invitations', `<button class="btn btn-primary" data-act="invite">${ic('plus')}Invite member</button>`)}<div class="card">${table([{ h: 'Member', f: u => `<a href="#/team/${u.id}"><b>${esc(u.name)}</b></a><div class="small muted">${esc(u.email)}</div>` }, { h: 'Role', f: u => u.role === 'owner' ? 'Owner' : 'AR Specialist' }, { h: 'Status', f: u => badge(u.status) }, { h: 'Last active', f: u => u.last || '—' }, { h: '', f: u => u.status === 'invited' ? `<button class="btn btn-sm" data-act="toast" data-msg="Invitation resent; the previous link no longer works">Resend</button> <button class="btn btn-sm" data-act="revoke" data-id="${u.id}">Revoke</button>` : '' }], D.users, { href: u => '#/team/' + u.id })}</div><div class="small muted mt8">Invited people join this organization. Accepting an invitation never creates a new one. Try it: <a href="auth.html#/invite/demo">open the invitation page</a>.</div>`, { name: 'team' });
ACT.invite = () => modal('Invite member', form('fi2', fld('Work email', '<input class="in" data-req data-email name="e" placeholder="name@company.com">', '', 'Enter a valid email address') + fld('Role', '<select class="in"><option>AR Specialist</option></select>', 'Owners are added by promoting an existing member.')), `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-primary" data-act="sendInvite">Send invitation</button>`);
ACT.sendInvite = () => { if (!validate($('#fi2'))) return; const e = $('[name=e]').value; if (D.users.some(u => u.email === e)) { toast('That person is already a member or invited'); return; } D.users.push({ id: 'u' + (++SEQ), name: e.split('@')[0], email: e, role: 'ar', status: 'invited', last: '' }); audit('member.invited', e, 'Role: AR Specialist'); closeOv(); toast('Invitation sent (single-use link, expires in 7 days)'); render(); };
ACT.revoke = el => { D.users.splice(D.users.findIndex(u => u.id === el.dataset.id), 1); toast('Invitation revoked'); render(); };
R(/^\/team\/(\w+)$/, m => {
  const u = user(m[1]); if (!u) return null; const own = u.role === 'owner';
  return `${pageH(esc(u.name) + ' ' + badge(u.status), esc(u.email), !own && u.status !== 'invited' ? `<button class="btn ${u.status === 'suspended' ? '' : 'btn-danger'}" data-act="susp" data-id="${u.id}">${u.status === 'suspended' ? 'Reactivate' : 'Suspend'}</button>` : '', '<a href="#/team">Team</a> / ' + esc(u.name))}
  <div class="grid g-main"><div>${card('Role and permissions', own ? `<div class="banner">${ic('lock')}<div>The Owner role has every permission and cannot be edited. At least one active Owner is always required.</div></div>` : `<div class="field"><label>Role</label><select class="in"><option>AR Specialist</option><option>Owner</option></select><div class="hint">Changing roles is audit-logged.</div></div><h3 class="mb16">AR Specialist permissions <span class="small muted">(shared by all AR Specialists)</span></h3>${permList()}`)}</div>
  <div>${card('Recent activity', mini(D.audit.filter(r => r[1] === u.id).slice(0, 5).map(r => `<li><span class="pt n"></span><div class="small">${esc(r[2])} · ${esc(r[3])}</div><div class="t">${r[0]}</div></li>`), 'No activity recorded.'))}</div></div>`;
}, { name: 'member' });
ACT.susp = el => { const u = user(el.dataset.id); u.status = u.status === 'suspended' ? 'active' : 'suspended'; audit('member.' + u.status, u.email, ''); toast(u.status === 'suspended' ? 'Suspended — blocked from their very next request' : 'Reactivated'); render(); };

/* ---------- audit log ---------- */
R(/^\/audit-log$/, () => {
  const v = vs('aud', { q: '', g: 'all' }); let rows = D.audit.filter(r => (r[2] + r[3] + r[4]).toLowerCase().includes((v.q || '').toLowerCase())); if (v.g !== 'all') rows = rows.filter(r => r[2].startsWith(v.g));
  return `${pageH('Audit log', 'Append-only record of security and financial events', `<button class="btn" data-act="toast" data-msg="Export queued; the export itself is audit-logged (simulated)">${ic('dl')}Export CSV</button>`)}<div class="card"><div class="toolbar">${searchIn('aud.q', 'Search actions and records')}${chipset('aud.g', [['all', 'All'], ['allocation', 'Allocations'], ['approval', 'Approvals'], ['investigation', 'Investigations'], ['member', 'Team'], ['integration', 'Integrations'], ['import', 'Imports']], v.g)}</div>${table([{ h: 'Time (UTC)', cls: 'nowrap', f: r => r[0] }, { h: 'Actor', f: r => r[1] === 'system' ? '<span class="badge b-neutral nodot">System</span>' : person(r[1]) }, { h: 'Action', f: r => `<span class="mono">${esc(r[2])}</span>` }, { h: 'Record', f: r => esc(r[3]) }, { h: 'Summary', f: r => esc(r[4]) }], rows, { attr: r => `data-aud="${D.audit.indexOf(r)}"` })}</div><div class="small muted mt8">Entries are written in the same transaction as the change, chained by hash, and cannot be edited or deleted by the application.</div>`;
}, { name: 'aud' });
document.addEventListener('click', e => { const tr = e.target.closest('[data-aud]'); if (tr) { const r = D.audit[+tr.dataset.aud]; drawer('Audit entry', `<dl class="kv"><dt>Time</dt><dd>${r[0]}</dd><dt>Action</dt><dd class="mono">${esc(r[2])}</dd><dt>Record</dt><dd>${esc(r[3])}</dd><dt>Summary</dt><dd>${esc(r[4])}</dd><dt>Request ID</dt><dd class="mono">req_8f2c1a</dd><dt>Hash</dt><dd class="mono">3e9a…b71c ← 91d0…44fa</dd></dl>`); } });

/* ---------- settings ---------- */
const STABS = [['company', 'Company'], ['financial', 'Financial'], ['approvals', 'Approvals'], ['notifications', 'Notifications'], ['roles', 'Roles'], ['remittance', 'Remittance'], ['security', 'Security'], ['data', 'Data']];
const sw = (on, l, h = '') => `<div class="row" style="padding:10px 0;border-bottom:1px solid var(--border)"><span class="sp"><b>${l}</b>${h ? `<div class="small muted">${h}</div>` : ''}</span><button class="switch ${on ? 'on' : ''}" role="switch" aria-checked="${on}" aria-label="${l}" data-act="sw"></button></div>`;
const saveBar = `<div class="row mt16"><button class="btn btn-primary" data-act="toast" data-msg="Settings saved and audit-logged (simulated)">Save changes</button></div>`;
R(/^\/settings\/(\w+)$/, m => {
  const t = m[1]; if (!STABS.some(s => s[0] === t)) return null; let b = '';
  if (t === 'company') b = form('sc', fld('Company name', '<input class="in" value="Brightpath Digital (demo)">') + fld('Legal name', '<input class="in" value="Brightpath Digital LLC">') + fld('Industry', '<select class="in"><option>Software development agency</option><option>IT consulting</option><option>Managed services</option></select>') + fld('Company size', '<select class="in"><option>11–50</option><option>51–200</option></select>') + fld('Website', '<input class="in" value="https://brightpath.example">')) + saveBar;
  if (t === 'financial') b = fld('Default currency', '<select class="in"><option>USD</option><option>EUR</option><option>GBP</option></select>') + fld('Timezone', '<select class="in"><option>America/New_York</option><option>Europe/London</option></select>', 'Used to decide when an invoice becomes overdue.') + fld('Default payment terms (days)', '<input class="in" type="number" value="30">') + fld('Short-payment grace (days)', '<input class="in" type="number" value="7">', 'Wait this long before flagging a short payment.') + fld('Claimed-payment grace (business days)', '<input class="in" type="number" value="5">') + sw(true, 'Auto-apply exact matches', 'Rule R1 only. Always visible in the Auto-applied tab with undo.') + saveBar;
  if (t === 'approvals') b = `<p class="small muted mb16">A policy decides whether an action needs a second person. Requesters never approve their own requests, except in a single-Owner organization (typed confirmation, logged as an owner direct action).</p>${table([{ h: 'Action', f: r => r[0] }, { h: 'Policy', f: r => r[1] }, { h: 'Threshold', f: r => r[2] }], [['Write-off', 'Always requires approval', '<span class="small muted">Locked</span>'], ['Refund record', 'Always requires approval', '<span class="small muted">Locked</span>'], ['Credit / discount', 'Requires approval above threshold', '<input class="in" style="height:30px;width:100px" value="0.00" aria-label="Credit and discount approval threshold"> USD'], ['Standard collection email', 'Approval unless sender may send', '<span class="small muted">Via permission</span>'], ['Final notice', 'Always requires approval', '<span class="small muted">Locked</span>'], ['Allocation reversal > 30 days old', 'Requires approval', '30 days']])}${saveBar}`;
  if (t === 'notifications') b = sw(true, 'Approval requested or decided') + sw(true, 'Assigned to me') + sw(true, 'Import finished or failed') + sw(false, 'Daily summary email') + saveBar;
  if (t === 'roles') b = `<p class="small muted mb16">Permissions for the AR Specialist role. Locked items stay with Owners in this version.</p>${permList()}`;
  if (t === 'remittance') b = `<div class="banner warn">${ic('lock')}<div>Remittance details appear in outgoing messages, so changing them is the highest-risk edit in Venn. Changes require re-authentication, notify every Owner, and show a banner for 24 hours.</div></div><dl class="kv"><dt>Account name</dt><dd>Brightpath Digital LLC</dd><dt>Account number</dt><dd class="mono">•••• •••• 4821</dd><dt>Routing</dt><dd class="mono">•••••0210</dd><dt>Last changed</dt><dd>Never</dd></dl><button class="btn mt16" data-act="chgRemit">Change remittance details</button>`;
  if (t === 'security') b = sw(true, 'Require two-factor authentication for Owners', 'Strongly recommended. Required before general availability.') + sw(false, 'Require two-factor authentication for everyone') + `<h3 class="mt24 mb16">Active sessions</h3>${table([{ h: 'Device', f: r => r[0] }, { h: 'Last active', f: r => r[1] }, { h: '', f: r => r[2] }], [['Chrome · New York', 'Now (this session)', ''], ['Safari · iPhone', '2 days ago', '<button class="btn btn-sm" data-act="toast" data-msg="Session revoked (simulated)">Revoke</button>']])}`;
  if (t === 'data') b = `<div class="row" style="padding:10px 0;border-bottom:1px solid var(--border)"><span class="sp"><b>Export organization data</b><div class="small muted">CSV bundle of customers, invoices, payments and allocations.</div></span><button class="btn" data-act="toast" data-msg="Export requested (simulated)">Request export</button></div><div class="row" style="padding:10px 0;border-bottom:1px solid var(--border)"><span class="sp"><b>Remove demo data</b><div class="small muted">Deletes only records marked as demonstration data.</div></span><button class="btn" data-act="toast" data-msg="Demo data removed (simulated)">Remove</button></div><div class="row" style="padding:10px 0"><span class="sp"><b>Request organization deletion</b><div class="small muted">30-day grace period, then a purge. Handled with support in this version.</div></span><button class="btn btn-danger" data-act="toast" data-msg="Request sent to support (simulated)">Request deletion</button></div>`;
  return `${pageH('Settings', 'Organization settings')}<div class="grid g-wide" style="grid-template-columns:200px minmax(0,1fr)"><nav class="card" style="padding:6px;align-self:start" aria-label="Settings sections">${STABS.map(s => `<a class="mi" style="display:block;padding:8px 10px;border-radius:6px;${s[0] === t ? 'background:var(--blue-50);color:var(--blue-600);font-weight:500' : 'color:var(--text)'}" href="#/settings/${s[0]}">${s[1]}</a>`).join('')}</nav>${card(STABS.find(s => s[0] === t)[1], b)}</div>`;
}, { name: 'set' });
ACT.chgRemit = () => modal('Confirm it is you', `<p class="small muted mb16">Re-authentication is required for this action.</p>` + form('fq', fld('Password', '<input class="in" type="password" data-req name="p" autocomplete="off">', 'Prototype: any value works; nothing is checked or stored.')) + fld('New account number', '<input class="in" placeholder="Prototype: not stored">'), `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-primary" data-act="doRemit">Change details</button>`);
ACT.doRemit = () => { if (!validate($('#fq'))) return; audit('remittance.changed', 'Organization', 'Fingerprint changed (values not logged)'); closeOv(); toast('Changed. All Owners were notified and a 24-hour banner is now shown.'); };

/* ---------- notifications, tasks, profile ---------- */
R(/^\/notifications$/, () => `${pageH('Notifications', '', `<button class="btn" data-act="readAll">Mark all read</button>`)}<div class="card"><div class="card-b flush">${D.notifications.filter(n => !n.perm || n.perm === S.role).map(n => `<a class="row" style="padding:14px 20px;border-bottom:1px solid var(--border);color:var(--text)" href="${n.link}"><div class="sp"><b>${esc(n.t)}</b> ${n.unread ? '<span class="badge b-blue nodot">new</span>' : ''}<div class="small muted">${esc(n.b)}</div></div><span class="cap">${n.at}</span></a>`).join('')}</div></div>`, { name: 'notif' });
ACT.readAll = () => { D.notifications.forEach(n => n.unread = false); render(); };
R(/^\/tasks$/, () => { const ts = D.tasks.filter(t => S.role === 'owner' || t.who === 'u2'); return `${pageH('My tasks', '')}<div class="card">${table([{ h: '', f: t => `<input type="checkbox" ${t.done ? 'checked' : ''} aria-label="Done" data-act="togTask" data-id="${t.id}">` }, { h: 'Task', f: t => `<a href="${t.link}" class="${t.done ? 'strike' : ''}">${esc(t.title)}</a>` }, { h: 'Due', f: t => dt(t.due) }], ts)}</div>`; }, { name: 'tasks' });
ACT.togTask = el => { const t = byId(D.tasks, el.dataset.id); t.done = !t.done; render(); };
R(/^\/profile$/, () => `${pageH('Profile and security')}<div class="grid g2">${card('Profile', `<dl class="kv"><dt>Name</dt><dd>${esc(me().name)}</dd><dt>Email</dt><dd>${esc(me().email)}</dd><dt>Role</dt><dd>${S.role === 'owner' ? 'Owner' : 'AR Specialist'}</dd></dl>`)}${card('Two-factor authentication', `<p class="small muted mb16">Add an authenticator app for a second sign-in step.</p><button class="btn" data-act="toast" data-msg="MFA setup (simulated)">Set up authenticator app</button>`)}${card('Notifications', sw(true, 'Approvals') + sw(true, 'Assignments') + sw(false, 'Daily summary'))}</div>`, { name: 'prof' });
